# /***************************************************************************
#  QGIS Plugin Analyzer
#
#  Auto-fix engine for applying code corrections.
#  ***************************************************************************/

import difflib
import pathlib
import subprocess
import tempfile
from abc import ABC, abstractmethod
from typing import Any, Dict, List

from .transformers import (
    GDALImportTransformer,
    I18nTransformer,
    LegacyImportTransformer,
    PrintToLogTransformer,
    apply_transformation,
)


def check_git_status(project_path: pathlib.Path) -> bool:
    """
    Checks if the working directory is clean.
    Returns True if clean, False if there are uncommitted changes.
    """
    try:
        result = subprocess.run(
            ["git", "status", "--porcelain"],
            cwd=project_path,
            capture_output=True,
            text=True,
            timeout=5,
        )
        return len(result.stdout.strip()) == 0
    except (subprocess.TimeoutExpired, FileNotFoundError):
        # Git not available or timeout
        return True  # Don't block if git is not available


def show_diff(file_path: pathlib.Path, original_content: str, new_content: str):
    """Displays a unified diff between original and new content."""
    diff = difflib.unified_diff(
        original_content.splitlines(keepends=True),
        new_content.splitlines(keepends=True),
        fromfile=f"a/{file_path.name}",
        tofile=f"b/{file_path.name}",
        lineterm="",
    )

    print("    " + "─" * 60)
    for line in diff:
        line = line.rstrip()
        if line.startswith("+++") or line.startswith("---"):
            print(f"    {line}")
        elif line.startswith("+"):
            print(f"    \033[32m{line}\033[0m")  # Green
        elif line.startswith("-"):
            print(f"    \033[31m{line}\033[0m")  # Red
        elif line.startswith("@@"):
            print(f"    \033[36m{line}\033[0m")  # Cyan
        else:
            print(f"    {line}")
    print("    " + "─" * 60)


class FixStrategy(ABC):
    """Abstract base class for fix strategies."""

    @abstractmethod
    def can_fix(self, issue: Dict[str, Any]) -> bool:
        """Returns True if this strategy can fix the given issue."""
        pass

    @abstractmethod
    def apply_fix(self, file_path: pathlib.Path, issue: Dict[str, Any]) -> bool:
        """Applies the fix to the file. Returns True if successful."""
        pass

    @abstractmethod
    def get_description(self, issue: Dict[str, Any]) -> str:
        """Returns a human-readable description of the fix."""
        pass


class GDALImportFixer(FixStrategy):
    """Fixes direct GDAL imports."""

    def can_fix(self, issue: Dict[str, Any]) -> bool:
        return issue.get("type") == "GDAL_DIRECT_IMPORT"

    def apply_fix(self, file_path: pathlib.Path, issue: Dict[str, Any]) -> bool:
        transformer = GDALImportTransformer()
        return apply_transformation(file_path, transformer)

    def get_description(self, issue: Dict[str, Any]) -> str:
        return "Replace 'import gdal' with 'from osgeo import gdal'"


class LegacyImportFixer(FixStrategy):
    """Fixes PyQt4/PyQt5 imports."""

    def can_fix(self, issue: Dict[str, Any]) -> bool:
        return issue.get("type") == "QGIS_LEGACY_IMPORT"

    def apply_fix(self, file_path: pathlib.Path, issue: Dict[str, Any]) -> bool:
        transformer = LegacyImportTransformer()
        return apply_transformation(file_path, transformer)

    def get_description(self, issue: Dict[str, Any]) -> str:
        return "Replace PyQt4/PyQt5 imports with qgis.PyQt"


class PrintToLogFixer(FixStrategy):
    """Fixes print() statements to use QgsMessageLog."""

    def can_fix(self, issue: Dict[str, Any]) -> bool:
        # This would need a new rule type in scanner.py
        return issue.get("type") == "PRINT_STATEMENT"

    def apply_fix(self, file_path: pathlib.Path, issue: Dict[str, Any]) -> bool:
        transformer = PrintToLogTransformer()
        return apply_transformation(file_path, transformer)

    def get_description(self, issue: Dict[str, Any]) -> str:
        return "Replace print() with QgsMessageLog.logMessage()"


class I18nFixer(FixStrategy):
    """Wraps hardcoded UI strings in self.tr()."""

    def can_fix(self, issue: Dict[str, Any]) -> bool:
        return issue.get("type") == "MISSING_I18N"

    def apply_fix(self, file_path: pathlib.Path, issue: Dict[str, Any]) -> bool:
        transformer = I18nTransformer()
        return apply_transformation(file_path, transformer)

    def get_description(self, issue: Dict[str, Any]) -> str:
        return "Wrap hardcoded string in self.tr() for internationalization"


class AutoFixer:
    """Orchestrates the auto-fix process."""

    def __init__(self, project_path: pathlib.Path, dry_run: bool = True):
        self.project_path = project_path
        self.dry_run = dry_run
        self.strategies: List[FixStrategy] = [
            GDALImportFixer(),
            LegacyImportFixer(),
            PrintToLogFixer(),
            I18nFixer(),
        ]

    def get_fixable_issues(self, issues: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Filters issues to only those that can be auto-fixed."""
        fixable = []
        for issue in issues:
            for strategy in self.strategies:
                if strategy.can_fix(issue):
                    issue["fixer"] = strategy
                    fixable.append(issue)
                    break
        return fixable

    def apply_fixes(
        self, issues: List[Dict[str, Any]], interactive: bool = True
    ) -> Dict[str, int]:
        """
        Applies fixes to the given issues.

        Returns a dict with counts: {'applied': N, 'skipped': M, 'failed': K}
        """
        stats = {"applied": 0, "skipped": 0, "failed": 0}

        # Git status check
        if not self.dry_run:
            is_clean = check_git_status(self.project_path)
            if not is_clean:
                print("\n⚠️  WARNING: Working directory has uncommitted changes.")
                print("   It's recommended to commit or stash changes before applying fixes.")
                if interactive:
                    response = input("   Continue anyway? [y/N]: ").lower()
                    if response != "y":
                        print("Aborted by user.")
                        return stats
                print()

        # Group by file
        by_file: Dict[str, List[Dict[str, Any]]] = {}
        for issue in issues:
            file_path = issue.get("file", "")
            if file_path not in by_file:
                by_file[file_path] = []
            by_file[file_path].append(issue)

        for file_rel, file_issues in by_file.items():
            file_path = self.project_path / file_rel

            print(f"\n📄 {file_rel}")

            # Read original content for diff
            try:
                original_content = file_path.read_text(encoding="utf-8")
            except Exception as e:
                print(f"  ❌ Error reading file: {e}")
                stats["failed"] += len(file_issues)
                continue

            for issue in file_issues:
                fixer: FixStrategy = issue["fixer"]
                description = fixer.get_description(issue)

                print(f"  Line {issue.get('line', '?')}: {description}")

                if interactive and not self.dry_run:
                    # Show diff preview

                    # Create temp file to test transformation
                    with tempfile.NamedTemporaryFile(mode='w', suffix='.py', delete=False) as tmp:
                        tmp.write(original_content)
                        tmp_path = pathlib.Path(tmp.name)

                    try:
                        fixer.apply_fix(tmp_path, issue)
                        new_content = tmp_path.read_text(encoding="utf-8")

                        if new_content != original_content:
                            show_diff(file_path, original_content, new_content)
                    finally:
                        tmp_path.unlink()

                    response = input("    Apply fix? [y/n/q]: ").lower()
                    if response == "q":
                        print("Aborted by user.")
                        return stats
                    if response != "y":
                        stats["skipped"] += 1
                        continue

                if not self.dry_run:
                    success = fixer.apply_fix(file_path, issue)
                    if success:
                        stats["applied"] += 1
                        print("    ✅ Applied")
                    else:
                        stats["failed"] += 1
                        print("    ❌ Failed")
                else:
                    stats["applied"] += 1  # Count as "would apply"

        return stats

# /***************************************************************************
#  QGIS Plugin Analyzer
#
#  Semantic analysis module for cross-file dependency and resource validation.
#  ***************************************************************************/

import pathlib
import xml.etree.ElementTree as ET
from typing import Any, Dict, List, Set


class DependencyGraph:
    """Builds and analyzes the module dependency graph."""

    def __init__(self):
        # Maps module path -> set of imported module paths
        self.adjacency_list: Dict[str, Set[str]] = {}
        # Maps module path -> metadata (imports, functions, etc.)
        self.nodes: Dict[str, Dict[str, Any]] = {}

    def add_node(self, module_path: str, data: Dict[str, Any]):
        """Adds a module node to the graph."""
        self.nodes[module_path] = data
        self.adjacency_list[module_path] = set()

    def build_edges(self, project_path: pathlib.Path):
        """Resolves imports to build edges between nodes."""
        for module_path, data in self.nodes.items():
            current_file = project_path / module_path
            current_dir = current_file.parent

            for imp in data.get("imports", []):
                resolved_path = self._resolve_import(imp, current_dir, project_path)
                if resolved_path and resolved_path in self.nodes:
                    self.adjacency_list[module_path].add(resolved_path)

    def _resolve_import(
        self, import_name: str, current_dir: pathlib.Path, project_path: pathlib.Path
    ) -> str:
        """Attempts to resolve a Python import string to a file path in the project."""
        # Handle relative imports (e.g., .utils)
        if import_name.startswith("."):
            # This is a simplification. Ideally AST gives better level info.
            # Assuming same package level for now if single dot
            parts = import_name.lstrip(".").split(".")
            target = current_dir.joinpath(*parts).with_suffix(".py")
            try:
                rel = str(target.relative_to(project_path))
                return rel
            except ValueError:
                pass
            return ""

        # Handle absolute imports within project
        parts = import_name.split(".")
        target = project_path.joinpath(*parts).with_suffix(".py")
        try:
            rel = str(target.relative_to(project_path))
            return rel
        except ValueError:
            # Maybe it is a package (__init__.py)
            target_pkg = project_path.joinpath(*parts) / "__init__.py"
            try:
                rel = str(target_pkg.relative_to(project_path))
                return rel
            except ValueError:
                pass
        return ""

    def detect_cycles(self) -> List[List[str]]:
        """Detects circular import cycles using DFS."""
        visited = set()
        recursion_stack = set()
        cycles = []

        def dfs(node, path):
            visited.add(node)
            recursion_stack.add(node)
            path.append(node)

            for neighbor in self.adjacency_list.get(node, []):
                if neighbor not in visited:
                    dfs(neighbor, path)
                elif neighbor in recursion_stack:
                    # Cycle found
                    cycle_start_index = path.index(neighbor)
                    cycles.append(path[cycle_start_index:] + [neighbor])

            recursion_stack.remove(node)
            path.pop()

        for node in self.nodes:
            if node not in visited:
                dfs(node, [])

        return cycles

    def get_coupling_metrics(self) -> Dict[str, Dict[str, int]]:
        """Calculates Fan-In and Fan-Out for each module."""
        metrics = {node: {"fan_in": 0, "fan_out": 0} for node in self.nodes}

        for source, targets in self.adjacency_list.items():
            metrics[source]["fan_out"] = len(targets)
            for target in targets:
                if target in metrics:  # Should always be true if graph valid
                    metrics[target]["fan_in"] += 1

        return metrics


class ResourceValidator:
    """Validates Qt resource usage against available qrc/py files."""

    def __init__(self, project_path: pathlib.Path):
        self.project_path = project_path
        self.available_resources: Set[str] = set()

    def scan_project_resources(self, ignore_matcher=None):
        """Scans .qrc files (and potentially converted _rc.py) to find valid resource paths."""
        # Strategy: Parse .qrc files primarily as they are the source of truth
        # Regex to find <file>path/to/icon.png</file> inside <qresource prefix="/plugins/myplugin">

        for qrc_file in self.project_path.rglob("*.qrc"):
            # Skip if matches ignore pattern
            if ignore_matcher and ignore_matcher.is_ignored(qrc_file):
                continue

            try:
                # Use standard xml.etree.ElementTree for robust parsing
                # Note: ElementTree is safe against XXE by default in Python 3.x
                # as it does not resolve entities unless a custom parser is provided.
                try:
                    tree = ET.parse(qrc_file)
                    root = tree.getroot()
                    for qresource in root.findall("qresource"):
                        prefix = qresource.get("prefix", "/")
                        if not prefix.startswith("/"):
                            prefix = "/" + prefix

                        for file_elem in qresource.findall("file"):
                            if file_elem.text:
                                clean_path = file_elem.text.strip()
                                # Construct full resource path: :/prefix/path
                                res_path = f":{prefix}/{clean_path}".replace("//", "/")
                                self.available_resources.add(res_path)
                except ET.ParseError:
                    pass  # Fallback or log warning

            except Exception:
                pass

    def validate_usage(self, resource_matches: List[str]) -> List[str]:
        """Returns a list of resource paths used in code but missing in definition."""
        missing = []
        for res in resource_matches:
            # Simple exact match check.
            # Note: Alias handling is complex without compilation, ignoring for now.
            if res not in self.available_resources:
                missing.append(res)
        return sorted(list(set(missing)))

